SELECT COALESCE(json_agg(row_to_json(t) ORDER BY function_identity), '[]'::json)::text FROM (SELECT 'public.m55_consult_reply_commit'::text AS function_identity, md5(pg_get_functiondef(p.oid)) AS definition_hash, length(pg_get_functiondef(p.oid))::int AS definition_character_length, pg_get_function_identity_arguments(p.oid) AS identity_arguments FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = 'm55_consult_reply_commit' AND pg_get_function_identity_arguments(p.oid) = 'p_user_id text, p_report_instance_id uuid, p_consult_thread_id uuid, p_idempotency_key text, p_user_message text, p_assistant_message text, p_message_created_at timestamp with time zone' UNION ALL SELECT 'public.m55_reply_generate_commit'::text AS function_identity, md5(pg_get_functiondef(p.oid)) AS definition_hash, length(pg_get_functiondef(p.oid))::int AS definition_character_length, pg_get_function_identity_arguments(p.oid) AS identity_arguments FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = 'm55_reply_generate_commit' AND pg_get_function_identity_arguments(p.oid) = 'p_user_id text, p_reply_session_id uuid, p_payload_json jsonb, p_theme text, p_generator_version text') t;